const meta = {
  component: Button,
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nRender a button or give another element the appearance of a button.\n\n**Import:** `@/registry/erbium/ui/button`\n\n## Usage\n\n```tsx\nimport { Button } from \"@/registry/erbium/ui/button\";\n```\n\n```tsx\n<Button variant=\"outline\">Button</Button>\n```\n\n## Cursor\n\nTailwind v4 [switched](https://tailwindcss.com/docs/upgrade-guide#buttons-use-the-default-cursor) from `cursor: pointer` to `cursor: default` for the button component.\n\nTo keep the `cursor: pointer` behavior, add `cursor-pointer` to your buttons.\n\nYou can also enable this during project setup with `npx shadcn@latest init --pointer`.\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Button](https://base-ui.com/react/components/button)",
      },
    },
  },
} satisfies Meta<typeof Button>;

export default { ...meta, title: "Components/Button",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

